      Check(pattern: #"count\s*\+=\s*1"#, ci: false, hint: #"count += 1"#)]),
  Mission(id: "kt1", lang: "kotlin", tier: 2, xp: 110, title: #"Android Underground"#, concept: #"data classes & null safety"#,
    brief: ["logos": #"Most of the world's believers carry Android phones. Model their profiles."#, "sentinel": #"Model malware samples pulled off seized Android devices."#, "meridian": #"Most phones in Meridian run Android. Model the contacts in our secure app."#],
    lesson: [LessonPart(code: false, text: #"Kotlin's data class gives you equals, copy and toString for free. ? marks nullable types, and ?: (the Elvis operator) supplies a fallback:"#), LessonPart(code: true, text: #"data class Contact(val name: String, val alias: String?)\#nval shown = c.alias ?: c.name"#)],
    task: #"Declare data class Contact(val name: String, val alias: String?) and write fun display(c: Contact) = c.alias ?: c.name."#, starter: #"// your code here\#n"#,
    checks: [Check(pattern: #"data\s+class\s+Contact\s*\("#, ci: false, hint: #"data class Contact(...)"#),
      Check(pattern: #"val\s+alias\s*:\s*String\?"#, ci: false, hint: #"val alias: String?"#),
      Check(pattern: #"fun\s+display\s*\(\s*c\s*:\s*Contact\s*\)"#, ci: false, hint: #"fun display(c: Contact)"#),
      Check(pattern: #"\?:"#, ci: false, hint: #"Use the Elvis operator ?:"#)]),
  Mission(id: "jv1", lang: "java", tier: 2, xp: 120, title: #"The Log4Shell Patch"#, concept: #"Classes, methods & validation"#,
    brief: ["logos": #"The Church's donation server runs Java. Make sure no one can turn its logs against it."#, "sentinel": #"December 2021. Every agency is scrambling. Write the input guard for the logger."#, "meridian": #"The aid-distribution system runs Java. Sanitize everything before it's logged."#],
    lesson: [LessonPart(code: false, text: #"Java organizes code into classes with typed methods:"#), LessonPart(code: true, text: #"public class Guard {\#n    public static boolean safe(String in) {\#n        return !in.contains("${");\#n    }\#n}"#), LessonPart(code: false, text: #"The real fix for Log4Shell was upgrading Log4j. Input checks are defense in depth, not a cure."#)],
    task: #"Write public class Sanitizer with public static String clean(String input) that returns input.replace("${", "")."#, starter: #"// your code here\#n"#,
    checks: [Check(pattern: #"public\s+class\s+Sanitizer"#, ci: false, hint: #"public class Sanitizer { ... }"#),
      Check(pattern: #"public\s+static\s+String\s+clean\s*\(\s*String\s+input\s*\)"#, ci: false, hint: #"public static String clean(String input)"#),
      Check(pattern: #"input\.replace\s*\(\s*"\$\{"\s*,\s*""\s*\)"#, ci: false, hint: #"return input.replace("${", "");"#)]),
  Mission(id: "cs1", lang: "csharp", tier: 2, xp: 120, title: #"Simulation Engine"#, concept: #"Classes, properties & LINQ"#,
    brief: ["logos": #"The Church is building a Unity simulation of the god's world. Model its entities."#, "sentinel": #"Build the C# training sim that rehearses a power-grid attack, like the 2015 Ukraine grid hack."#, "meridian": #"Build a Unity sim so volunteers can rehearse evacuation routes."#],
    lesson: [LessonPart(code: false, text: #"C# uses properties with { get; set; }. LINQ queries collections like SQL:"#), LessonPart(code: true, text: #"public class Unit {\#n    public string Name { get; set; }\#n    public int Hp { get; set; }\#n}\#nvar alive = units.Where(u => u.Hp > 0).ToList();"#)],
    task: #"Define public class Unit with Name and Hp properties, then use units.Where( to get units with Hp > 0 and call .ToList()."#, starter: #"using System.Linq;\#n\#n// your code here\#n"#,
    checks: [Check(pattern: #"public\s+class\s+Unit"#, ci: false, hint: #"public class Unit"#),
      Check(pattern: #"public\s+string\s+Name\s*\{\s*get;\s*set;\s*\}"#, ci: false, hint: #"public string Name { get; set; }"#),
      Check(pattern: #"public\s+int\s+Hp\s*\{\s*get;\s*set;\s*\}"#, ci: false, hint: #"public int Hp { get; set; }"#),
      Check(pattern: #"units\.Where\s*\(\s*\w+\s*=>\s*\w+\.Hp\s*>\s*0\s*\)\s*\.ToList\(\)"#, ci: false, hint: #"units.Where(u => u.Hp > 0).ToList()"#)]),
  Mission(id: "cpp1", lang: "cpp", tier: 3, xp: 170, title: #"Heartbleed Autopsy"#, concept: #"Bounds checking & vectors"#,
    brief: ["logos": #"The god's core runs in C++. One unchecked index and it reads its own corrupted memory."#, "sentinel": #"Heartbleed, 2014: a missing length check leaked server memory. Never again."#, "meridian": #"Our radio firmware is C++. One overflow and the occupation owns every handset."#],
    lesson: [LessonPart(code: false, text: #"C++ trusts you completely, which is dangerous. Heartbleed happened because code trusted a length the attacker supplied. Always check bounds, or use .at(), which throws instead of reading garbage:"#), LessonPart(code: true, text: #"#include <vector>\#nint read(const std::vector<int>& v, size_t i) {\#n    if (i >= v.size()) return -1;\#n    return v[i];\#n}"#)],
    task: #"Write int safeRead(const std::vector<int>& buf, size_t i) that returns -1 if i >= buf.size(), otherwise buf[i]."#, starter: #"#include <vector>\#n\#n// your code here\#n"#,
    checks: [Check(pattern: #"int\s+safeRead\s*\(\s*const\s+std::vector<int>\s*&\s*buf\s*,\s*size_t\s+i\s*\)"#, ci: false, hint: #"int safeRead(const std::vector<int>& buf, size_t i)"#),
      Check(pattern: #"i\s*>=\s*buf\.size\(\)|buf\.size\(\)\s*<=\s*i"#, ci: false, hint: #"if (i >= buf.size())"#),
      Check(pattern: #"return\s+-1"#, ci: false, hint: #"return -1;"#),
      Check(pattern: #"return\s+buf\[\s*i\s*\]|return\s+buf\.at\(\s*i\s*\)"#, ci: false, hint: #"return buf[i];"#)]),
]

